      "phrases": [
        {
          "id": "V2-01",
          "zh": "阳台外 风穿过栏杆"
        },
        {
          "id": "V2-02",
          "zh": "楼梯上 脚步声一级一级"
        },
        {
          "id": "V2-03",
          "zh": "天暗下来 云压得很低"
        },
        {
          "id": "V2-04",
          "zh": "落在窗玻璃上 落在房间地板"
        },
        {
          "id": "V2-05",
          "zh": "黄昏正一点一点散开"
        },
        {
          "id": "V2-06",
          "zh": "夕阳红得像 一双哭肿的眼睛"
        },
        {
          "id": "V2-07",
          "zh": "像要融化一样 一点一点"
        },
        {
          "id": "V2-08",
          "zh": "世界就一点一点 一点点死去"
        },
        {
          "id": "V2-09",
          "zh": "梦见我双手 一寸一寸收紧你喉咙"
        },
        {
          "id": "V2-10",
          "zh": "春风里 窗帘轻轻地晃动"
        },
        {
          "id": "V2-11",
          "zh": "干裂的嘴唇 轻轻张开 却说不出"
        },
        {
          "id": "V2-12",
          "zh": "漏出的话 像泡沫一样 一碰就破"
        }
      ]
    }
  ]
}

